}catch(Throwable $e){error_log('attendance-report-safe-v3: '.$e->getMessage().' @ '.$e->getFile().':'.$e->getLine());afv_error('خطای داخلی گزارش تردد؛ جزئیات در گزارش خطای سرور ثبت شد.',500);}
